/**
 * Inline (base64 data URL) version of the ST Putra Settu Bhakti Jaya emblem.
 *
 * The logo is embedded directly as a data URL instead of being served from
 * "/logo-stt.png". Mobile WebKit (iOS Safari) and mobile Chrome frequently drop
 * external <img> sources while an image is rasterised, which made the logo
 * disappear on downloads taken from a phone. An inline data URL removes the
 * network request entirely so the logo always renders. The server-side KTA
 * renderer (`/api/kta/[id]`) inlines it the same way.
 *
 * The source art was resized to 512x512 and PNG-optimised (~86 KB) to keep the
 * bundle small while staying sharp for the 3x export of the 260px watermark.
 *
 * Do not edit by hand — regenerate from public/logo-stt.png if the art changes.
 */
export const LOGO_STT_DATA_URL =
  "data:image/png;base64,";

/**
 * Inline (Base64) avatar fallback used when a member has no profile photo, or
 * when the photo cannot be fetched while the KTA is rendered on the server.
 * Kept in this server-safe module (no "use client") so both the API route and
 * the browser can import it.
 */
export const DEFAULT_AVATAR_DATA_URL =
  "data:image/svg+xml;base64,";
